mapper.select:
SELECT COUNT(*)
FROM PAY_CALLBACK_LOG
WHERE MERCHANT_ORDER_NO = #{merchantOrderNo,jdbcType=VARCHAR}
  AND CALLBACK_TYPE = #{callbackType,jdbcType=VARCHAR}

mapper.update:
UPDATE PAY_CALLBACK_LOG
SET HANDLE_STATUS = 'MANUAL',
    HANDLE_MSG = #{handleMsg,jdbcType=VARCHAR}
WHERE ID = (
    SELECT MAX(ID)
    FROM PAY_CALLBACK_LOG
    WHERE MERCHANT_ORDER_NO = #{merchantOrderNo,jdbcType=VARCHAR}
      AND CALLBACK_TYPE = #{callbackType,jdbcType=VARCHAR}
)
